import{_ as t,o,c as n,a2 as a}from"./chunks/framework.Buc7gXeZ.js";const m=JSON.parse('{"title":"Managing Employee Permissions","description":"","frontmatter":{},"headers":[],"relativePath":"user-guide/permissions.md","filePath":"user-guide/permissions.md"}'),s={name:"user-guide/permissions.md"};function r(i,e,l,d,h,c){return o(),n("div",null,[...e[0]||(e[0]=[a('<h1 id="managing-employee-permissions" tabindex="-1">Managing Employee Permissions <a class="header-anchor" href="#managing-employee-permissions" aria-label="Permalink to &quot;Managing Employee Permissions&quot;">​</a></h1><p>A practical guide for system administrators: how to give an employee access to something in the system, and how to take it away.</p><h2 id="the-core-idea" tabindex="-1">The core idea <a class="header-anchor" href="#the-core-idea" aria-label="Permalink to &quot;The core idea&quot;">​</a></h2><p>An employee&#39;s permissions in TagERP are <strong>never set on the employee directly</strong> — they&#39;re an automatic result of five things on their employment record:</p><ol><li><strong>Company</strong> they work for</li><li><strong>Branch</strong> they work at</li><li><strong>Department</strong> they belong to</li><li><strong>Job title</strong></li><li><strong>Job grade</strong></li></ol><p>To grant someone access, you don&#39;t go looking for a &quot;permissions screen&quot; and tick boxes — you <strong>set these five fields correctly</strong>, and the system computes everything else on its own. If an employee moves from Procurement to Finance, their permissions change automatically, the moment you save — no extra step.</p><h2 id="the-two-things-that-get-decided" tabindex="-1">The two things that get decided <a class="header-anchor" href="#the-two-things-that-get-decided" aria-label="Permalink to &quot;The two things that get decided&quot;">​</a></h2><p>Every employee has two completely separate dimensions, and both need to be set correctly:</p><h3 id="_1-which-data-they-ll-see-scope" tabindex="-1">1. Which data they&#39;ll see (scope) <a class="header-anchor" href="#_1-which-data-they-ll-see-scope" aria-label="Permalink to &quot;1. Which data they&#39;ll see (scope)&quot;">​</a></h3><p>Set via two fields when adding/editing the employee:</p><table tabindex="0"><thead><tr><th>Field</th><th>Available values</th><th>What it means</th></tr></thead><tbody><tr><td><strong>Company scope</strong></td><td>Own records only / Own branch / Whole company / Company + subsidiaries</td><td>A regular employee is usually &quot;own branch&quot;. A group-level department manager is usually &quot;company + subsidiaries&quot;</td></tr><tr><td><strong>Department scope</strong></td><td>Own records only / This department / Department + sub-departments / Every department</td><td>A department manager is usually &quot;department + sub-departments&quot;</td></tr></tbody></table><p><strong>Worked example:</strong> A finance manager at the parent company, with company scope &quot;company + subsidiaries&quot; and department scope &quot;department + sub-departments&quot;, sees Finance data across <strong>every</strong> company in the group. The same manager, if stationed at a subsidiary instead, with company scope &quot;whole company&quot; only (not &quot;+ subsidiaries&quot;), sees Finance data for <strong>that company only</strong> — not the rest of the group.</p><h3 id="_2-which-screens-they-can-open-functional-permissions" tabindex="-1">2. Which screens they can open (functional permissions) <a class="header-anchor" href="#_2-which-screens-they-can-open-functional-permissions" aria-label="Permalink to &quot;2. Which screens they can open (functional permissions)&quot;">​</a></h3><p>This is decided automatically by the employee&#39;s <strong>department</strong>, <strong>job title</strong>, and <strong>grade</strong> — never set on the person directly.</p><ul><li>An employee in the <strong>Finance</strong> department can open the Finance module automatically. Someone outside it cannot open it at all.</li><li>A job title like &quot;General Accountant&quot; carries specific permissions (e.g. viewing journal entries) that apply to everyone holding that title.</li><li>Some permissions are also tied to grade — e.g. a &quot;General Accountant&quot; at <strong>senior</strong> grade can post a journal entry; the same title at junior grade cannot, even though both can see the same screen.</li></ul><h2 id="how-to-grant-an-employee-access" tabindex="-1">How to grant an employee access <a class="header-anchor" href="#how-to-grant-an-employee-access" aria-label="Permalink to &quot;How to grant an employee access&quot;">​</a></h2><ol><li>Open the <strong>Employees</strong> screen (HR → Employee Management).</li><li>Add the employee (or open their existing record) and set: <ul><li>Company and branch</li><li>Department</li><li>Job title</li><li>Job grade</li><li>Company scope and department scope (see the table above)</li></ul></li><li>Save. Permissions take effect <strong>immediately</strong> — no extra step, no waiting period.</li></ol><p><strong>If the job title, department, or grade you need doesn&#39;t exist yet?</strong> It has to be added first, from its own screen (Organization Structure → Departments / Job Titles / Job Grades), before you can select it on an employee.</p><h2 id="how-to-revoke-an-employee-s-access" tabindex="-1">How to revoke an employee&#39;s access <a class="header-anchor" href="#how-to-revoke-an-employee-s-access" aria-label="Permalink to &quot;How to revoke an employee&#39;s access&quot;">​</a></h2><p>Three approaches depending on the situation:</p><table tabindex="0"><thead><tr><th>Situation</th><th>What to do</th></tr></thead><tbody><tr><td><strong>Employee isn&#39;t working right now</strong> (temporary leave/suspension)</td><td>Set status to <strong>&quot;Suspended&quot;</strong> — every permission is lost immediately, restored the moment status returns to &quot;Active&quot;</td></tr><tr><td><strong>Employee&#39;s contract ended / resigned permanently</strong></td><td>Set status to <strong>&quot;Terminated&quot;</strong> — same effect, permanent</td></tr><tr><td><strong>Employee is still working but needs different/reduced access</strong></td><td>Change their job title/department/grade to match the new situation — permissions update automatically the moment you save</td></tr></tbody></table><p>⚠️ <strong>Important:</strong> Deleting the employee record is <strong>not</strong> the correct way to revoke access — always use &quot;Suspended&quot;/&quot;Terminated&quot; so their history stays on record.</p><h2 id="faq" tabindex="-1">FAQ <a class="header-anchor" href="#faq" aria-label="Permalink to &quot;FAQ&quot;">​</a></h2><p><strong>Q: I want an employee to see everything in Finance but not edit anything.</strong> This is decided by the <strong>job title</strong> assigned to them — there needs to be a job title already defined with &quot;view only&quot; permissions. If none exists, ask the development/admin team to add one.</p><p><strong>Q: I want to give a manager access to two specific branches, not the whole company.</strong> The system currently supports &quot;own branch&quot; or &quot;whole company&quot; — there&#39;s no &quot;two specific branches&quot; option yet. If you genuinely need this, report it to the development team.</p><p><strong>Q: I made the change but the employee still sees/doesn&#39;t see the old screen.</strong> Make sure the employee logged out and back in — or wait a moment; permissions update immediately in the database, but the browser may still be holding an old copy of the sidebar.</p><p><strong>Q: Someone has a permission they shouldn&#39;t, and I&#39;m sure I set their record up correctly.</strong> This is rare, but can happen if someone edited the job title&#39;s own permissions directly without saving any employee record. Ask the development team to run the permission-reconciliation command (<code>hr:permissions:reconcile</code>), which detects and fixes any drift automatically.</p>',27)])])}const u=t(s,[["render",r]]);export{m as __pageData,u as default};
